package com.pulsesg.support.service; import com.pulsesg.support.entity.Ticket; import org.springframework.stereotype.Service; @Service public class MockAiSuggestionService implements AiSuggestionService {public String suggest(Ticket t){String urgency=switch(t.getPriority()){case CRITICAL,HIGH->"This is marked as a high-priority request, so we are treating it with urgency.";default->"Thanks for sharing the details; we are reviewing this carefully.";};return urgency+" Based on your "+t.getCategory().name().toLowerCase()+" issue, the next best step is to confirm the exact impact and any recent changes. We will follow up with a clear resolution path shortly.";}}
